SELECT *
FROM proj_task_state_machine_revision
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.revisionId}
  AND deleted = b'0'
FOR UPDATE

SELECT *
FROM proj_task_state_transition
WHERE tenant_id = #{query.tenantId}
  AND revision_id = #{query.revisionId}
  AND deleted = b'0'
ORDER BY from_status_code, action_code, id

SELECT *
FROM proj_task_state_transition
WHERE tenant_id = #{query.tenantId}
  AND revision_id = #{query.revisionId}
  AND from_status_code = #{query.fromStatusCode}
  AND action_code = #{query.actionCode}
  AND deleted = b'0'

mapper.update:
UPDATE proj_task_state_machine_revision
SET status = 'PUBLISHED',
    published_by = #{query.publishedBy},
    published_at = #{query.publishedAt},
    version = version + 1,
    updater = #{query.updater},
    update_time = #{query.publishedAt}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.revisionId}
  AND status = 'DRAFT'
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
